import { useState } from 'react';
import styles from './AdminShared.module.css';
import LoadState, { ActionFeedback } from '../components/LoadState';
import AdjustPointsForm from '../components/loyalty/AdjustPointsForm';
import RedemptionTable from '../components/loyalty/RedemptionTable';
import RewardForm from '../components/loyalty/RewardForm';
import RewardRow from '../components/loyalty/RewardRow';
import WalletTable from '../components/loyalty/WalletTable';
import { useRowAction } from '../hooks/useRowAction';
import {
  useAdminRewards,
  useRedemptions,
  useWallets,
  type AdjustAction,
  type Reward,
  type RewardChanges,
  type RewardInput,
  type Wallet,
} from '../hooks/useLoyaltyAdmin';

// Aba "Fidelidade" do painel, só do admin (SPEC/2026-11-26-painel-fidelidade.md): os prêmios, com
// criação, edição e desativação confirmada, as carteiras com o ajuste manual de pontos (motivo
// obrigatório e confirmação) e o histórico de resgates.

/** Formulário de prêmio aberto: nenhum, o de criação ou o de edição de um prêmio. */
type Editing = null | 'new' | Reward;

const AdminLoyalty = () => {
  const { rewards, status, loadError, reload, createReward, updateReward, deactivateReward } = useAdminRewards();
  const wallets = useWallets();
  const redemptions = useRedemptions();
  const [editing, setEditing] = useState<Editing>(null);
  const [adjusting, setAdjusting] = useState<Wallet | null>(null);
  const { busyId, message, actionError, run, clear, setMessage } = useRowAction();

  const open = (target: Editing) => {
    clear();
    setAdjusting(null);
    setEditing(target);
  };

  const openAdjust = (wallet: Wallet) => {
    clear();
    setEditing(null);
    setAdjusting(wallet);
  };

  const save = async (data: RewardInput | RewardChanges) => {
    if (editing === 'new') {
      await createReward(data as RewardInput);
      setMessage('Prêmio criado.');
    } else if (editing) {
      await updateReward(editing.id, data);
      setMessage('Prêmio atualizado.');
    }
    setEditing(null);
  };

  const deactivate = (reward: Reward) => {
    if (editing !== 'new' && editing?.id === reward.id) setEditing(null);
    run(reward.id, () => deactivateReward(reward.id), 'Prêmio desativado. Ele saiu do catálogo.');
  };

  const adjust = async (action: AdjustAction, points: number, reason: string) => {
    if (!adjusting) return;
    await wallets.adjust(adjusting, action, points, reason);
    setMessage(action === 'add' ? 'Pontos adicionados.' : 'Pontos retirados.');
    setAdjusting(null);
  };

  return (
    <div className={styles.adminContainer}>
      <div className={styles.header}>
        <h2 className={styles.title}>🎁 Fidelidade</h2>
        <button className={styles.btnAction} onClick={() => open('new')} disabled={status !== 'ready'}>
          + Novo prêmio
        </button>
      </div>

      {editing && (
        <RewardForm
          // Trocar de prêmio recria o formulário com os dados do novo.
          key={editing === 'new' ? 'new' : editing.id}
          reward={editing === 'new' ? undefined : editing}
          onSave={save}
          onCancel={() => setEditing(null)}
        />
      )}

      {adjusting && <AdjustPointsForm wallet={adjusting} onSave={adjust} onCancel={() => setAdjusting(null)} />}

      <ActionFeedback message={message} error={actionError} />

      <h3 className={styles.title}>Prêmios</h3>
      <LoadState status={status} loadError={loadError} reload={reload} loadingText="Carregando prêmios...">
        {rewards.length === 0 ? (
          <p>Nenhum prêmio cadastrado.</p>
        ) : (
          <table className={styles.table} aria-label="Prêmios">
            <thead>
              <tr>
                <th>Prêmio</th>
                <th>Custo</th>
                <th>Ações</th>
              </tr>
            </thead>
            <tbody>
              {rewards.map((reward) => (
                <RewardRow
                  key={reward.id}
                  reward={reward}
                  busy={busyId === reward.id}
                  onEdit={open}
                  onDeactivate={deactivate}
                />
              ))}
            </tbody>
          </table>
        )}
      </LoadState>

      <h3 className={styles.title} style={{ marginTop: '2.5rem' }}>Carteiras</h3>
      <LoadState status={wallets.status} loadError={wallets.loadError} reload={wallets.reload} loadingText="Carregando carteiras...">
        <WalletTable wallets={wallets.wallets} busy={adjusting !== null} onAdjust={openAdjust} />
      </LoadState>

      <h3 className={styles.title} style={{ marginTop: '2.5rem' }}>Resgates</h3>
      <LoadState
        status={redemptions.status}
        loadError={redemptions.loadError}
        reload={redemptions.reload}
        loadingText="Carregando resgates..."
      >
        <RedemptionTable redemptions={redemptions.redemptions} wallets={wallets.wallets} />
      </LoadState>
    </div>
  );
};

export default AdminLoyalty;
import { useCallback } from 'react';
import api from '../api';
import { upsert } from './useNameList';
import { useApiResource } from './useApiResource';

// Fidelidade no painel do admin: prêmios, carteiras com o ajuste manual de pontos e o histórico
// de resgates, com as rotas de /loyalty (SPEC/2026-11-26-painel-fidelidade.md). As ações devolvem
// o que o backend gravou e lançam o erro da API, para quem chamou mostrar a mensagem.

export type Reward = {
  id: string;
  name: string;
  description: string | null;
  points_cost: number;
  is_active: boolean;
  created_at: string;
};

/** Campos da criação, já no formato da API. */
export type RewardInput = Pick<Reward, 'name' | 'description' | 'points_cost'>;
/** Alteração parcial: só os campos que mudaram. */
export type RewardChanges = Partial<RewardInput>;

export type Wallet = {
  id: string;
  user_id: string;
  balance: number;
  lifetime_points: number;
  updated_at: string;
  full_name: string;
  email: string;
};

export type Redemption = {
  id: string;
  wallet_id: string;
  user_id: string;
  reward_id: string;
  points_spent: number;
  redeemed_at: string;
  reward: Reward;
};

/** Adicionar ou retirar pontos: o fim da rota (`/wallet/{id}/add` ou `/remove`). */
export type AdjustAction = 'add' | 'remove';

/** Mesma ordem do backend: do prêmio mais barato para o mais caro. */
const byCost = (a: Reward, b: Reward) => a.points_cost - b.points_cost;

/** Mesma ordem do backend: do maior saldo para o menor, e pelo nome. */
const byBalance = (a: Wallet, b: Wallet) => b.balance - a.balance || a.full_name.localeCompare(b.full_name, 'pt-BR');

const loadRewards = async () => (await api.get<Reward[]>('/loyalty/rewards')).data;
const loadWallets = async () => (await api.get<Wallet[]>('/loyalty/wallets')).data;
const loadRedemptions = async () => (await api.get<Redemption[]>('/loyalty/redemptions')).data;

export function useAdminRewards() {
  const { data: rewards, setData, status, loadError, reload } = useApiResource(
    loadRewards,
    [] as Reward[],
    'Não foi possível carregar os prêmios.',
  );

  const createReward = useCallback(
    async (input: RewardInput) => {
      const saved = (await api.post<Reward>('/loyalty/rewards', input)).data;
      setData((current) => upsert(current, saved, byCost));
      return saved;
    },
    [setData],
  );

  /** O PUT com `is_active: false` desativa: o prêmio sai desta lista, que só tem os ativos. */
  const updateReward = useCallback(
    async (id: string, changes: RewardChanges | { is_active: false }) => {
      const saved = (await api.put<Reward>(`/loyalty/rewards/${id}`, changes)).data;
      setData((current) =>
        saved.is_active ? upsert(current, saved, byCost) : current.filter((r) => r.id !== saved.id),
      );
      return saved;
    },
    [setData],
  );

  const deactivateReward = useCallback((id: string) => updateReward(id, { is_active: false }), [updateReward]);

  return { rewards, status, loadError, reload, createReward, updateReward, deactivateReward };
}

export function useWallets() {
  const { data: wallets, setData, status, loadError, reload } = useApiResource(
    loadWallets,
    [] as Wallet[],
    'Não foi possível carregar as carteiras.',
  );

  /** Ajusta o saldo com o motivo. A resposta não traz o cliente: ele continua o da linha. */
  const adjust = useCallback(
    async (wallet: Wallet, action: AdjustAction, points: number, reason: string) => {
      const { data } = await api.post<Omit<Wallet, 'full_name' | 'email'>>(
        `/loyalty/wallet/${wallet.user_id}/${action}`,
        null,
        { params: { points, reason } },
      );
      const saved: Wallet = { ...wallet, ...data };
      setData((current) => upsert(current, saved, byBalance));
      return saved;
    },
    [setData],
  );

  return { wallets, status, loadError, reload, adjust };
}

export function useRedemptions() {
  const { data: redemptions, status, loadError, reload } = useApiResource(
    loadRedemptions,
    [] as Redemption[],
    'Não foi possível carregar os resgates.',
  );
  return { redemptions, status, loadError, reload };
}
import { useCallback, useEffect, useState } from 'react';
import { apiErrorMessage } from '../utils/apiError';

// Carga de dados da API com "carregando", erro em português e "Tentar de novo". Usado pelo
// painel de serviços (SPEC/2026-11-23-painel-servicos.md) e por Meus agendamentos
// (SPEC/2026-11-25-meus-agendamentos.md). `setData` deixa quem usa atualizar a lista depois
// de uma ação, sem carregar de novo. `load` precisa ser estável (função do módulo ou
// useCallback): uma função nova a cada renderização carregaria de novo a cada renderização.

export type LoadStatus = 'loading' | 'ready' | 'error';

export function useApiResource<T>(load: () => Promise<T>, initial: T, fallbackError: string) {
  const [data, setData] = useState<T>(initial);
  const [status, setStatus] = useState<LoadStatus>('loading');
  const [loadError, setLoadError] = useState('');
  // Mudar o número pede uma nova carga ("Tentar de novo").
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let active = true;
    setStatus('loading');
    load()
      .then((loaded) => {
        if (!active) return;
        setData(loaded);
        setStatus('ready');
      })
      .catch((error) => {
        if (!active) return;
        setLoadError(apiErrorMessage(error, fallbackError));
        setStatus('error');
      });
    return () => {
      active = false;
    };
  }, [attempt, load, fallbackError]);

  const reload = useCallback(() => setAttempt((n) => n + 1), []);

  return { data, setData, status, loadError, reload };
}
import { useCallback, useState } from 'react';
import { apiErrorMessage } from '../utils/apiError';

// Ação sobre uma linha de uma tabela do painel: a linha fica ocupada enquanto a ação roda, e o
// resultado aparece no topo, como mensagem ou erro da API. Usado pelos painéis de serviços
// (SPEC/2026-11-23-painel-servicos.md) e de usuários (SPEC/2026-11-25-admin-usuarios.md).

export function useRowAction() {
  const [busyId, setBusyId] = useState<string | null>(null);
  const [message, setMessage] = useState('');
  const [actionError, setActionError] = useState('');

  const clear = useCallback(() => {
    setMessage('');
    setActionError('');
  }, []);

  /** Roda `action` com a linha `id` ocupada. Devolve o resultado, ou undefined se falhou. */
  const run = useCallback(
    async <T,>(id: string, action: () => Promise<T>, done: string): Promise<T | undefined> => {
      clear();
      setBusyId(id);
      try {
        const result = await action();
        setMessage(done);
        return result;
      } catch (error) {
        setActionError(apiErrorMessage(error, 'Não foi possível concluir a ação.'));
        return undefined;
      } finally {
        setBusyId(null);
      }
    },
    [clear],
  );

  return { busyId, message, actionError, run, clear, setMessage };
}
import { useCallback } from 'react';
import api from '../api';
import { useApiResource } from './useApiResource';

// Lista de nomes do painel (categorias de despesa e tags da galeria): carrega de `path`, cria
// com POST, renomeia com PUT `path/{id}` e apaga com DELETE, mantendo a ordem alfabética do
// backend (SPEC/2026-11-26-painel-despesas.md e SPEC/2026-11-26-painel-galeria.md). As ações
// devolvem o que o backend gravou e lançam o erro da API, para quem chamou mostrar a mensagem.

export type NamedItem = { id: string; name: string };

export const byName = (a: NamedItem, b: NamedItem) => a.name.localeCompare(b.name, 'pt-BR', { sensitivity: 'base' });

/** Põe `saved` na lista, no lugar do item de mesmo id ou como novo, e ordena. */
export function upsert<T extends { id: string }>(list: T[], saved: T, order: (a: T, b: T) => number): T[] {
  return [...list.filter((item) => item.id !== saved.id), saved].sort(order);
}

export function useNameList<T extends NamedItem>(path: string, loadErrorText: string) {
  const load = useCallback(async () => (await api.get<T[]>(path)).data, [path]);
  const { data: items, setData, status, loadError, reload } = useApiResource(load, [] as T[], loadErrorText);

  const store = useCallback((saved: T) => {
    setData((current) => upsert(current, saved, byName));
    return saved;
  }, []);

  const create = useCallback(async (name: string) => store((await api.post<T>(path, { name })).data), [path, store]);

  const rename = useCallback(
    async (id: string, name: string) => store((await api.put<T>(`${path}/${id}`, { name })).data),
    [path, store],
  );

  const remove = useCallback(
    async (id: string) => {
      await api.delete(`${path}/${id}`);
      setData((current) => current.filter((item) => item.id !== id));
    },
    [path],
  );

  return { items, status, loadError, reload, create, rename, remove };
}

export type NameListResource<T extends NamedItem> = ReturnType<typeof useNameList<T>>;

