type Mock = ReturnType<typeof vi.fn>;
const mocked = api as unknown as { get: Mock; post: Mock; put: Mock };

beforeEach(() => {
  for (const fn of Object.values(mocked)) fn.mockReset();
});

async function ready<T extends { status: string }>(hook: () => T) {
